import statistics

def detect_anomalies(data, threshold=3.0):
    if len(data) < 2:
        return []
    mean = statistics.mean(data)
    std = statistics.stdev(data)
    if std == 0:
        return []
    return [i for i, x in enumerate(data) if abs((x - mean) / std) > threshold]

