def exponential_backoff(attempt, base=1.0, max_delay=60.0, jitter=True):
    delay = min(base * (2 ** attempt), max_delay)
    if jitter:
        delay *= (0.5 + random.random() * 0.5)
    return delay

def retry_with_backoff(fn, max_attempts=5):
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception as e:
            if attempt == max_attempts - 1:
                raise
            time.sleep(exponential_backoff(attempt))

import hashlib

class BloomFilter:
    def __init__(self, size=1000, num_hashes=3):
        self.size = size
        self.num_hashes = num_hashes
        self.bit_array = bytearray(size)

    def _hashes(self, item):
        result = []
        for i in range(self.num_hashes):
            h = hashlib.md5(f'{i}{item}'.encode()).hexdigest()
            result.append(int(h, 16) % self.size)
        return result

    def add(self, item):
        for idx in self._hashes(item):
            self.bit_array[idx] = 1

    def contains(self, item):
        return all(self.bit_array[idx] for idx in self._hashes(item))

