def jaccard_similarity(set_a, set_b):
    set_a = set(set_a)
    set_b = set(set_b)
    intersection = set_a & set_b
    union = set_a | set_b
    if not union:
        return 1.0
    return len(intersection) / len(union)

import hashlib
import bisect

class ConsistentHash:
    def __init__(self, nodes=None, replicas=100):
        self.replicas = replicas
        self.ring = {}
        self.sorted_keys = []
        for node in (nodes or []):
            self.add_node(node)

    def _hash(self, key):
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, node):
        for i in range(self.replicas):
            key = self._hash(f'{node}:{i}')
            self.ring[key] = node
            bisect.insort(self.sorted_keys, key)

    def get_node(self, key):
        if not self.ring:
            return None
        h = self._hash(key)
        idx = bisect.bisect(self.sorted_keys, h) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[idx]]

def deduplicate(records, key_fields):
    seen = set()
    unique = []
    for record in records:
        key = tuple(record.get(f) for f in key_fields)
        if key not in seen:
            seen.add(key)
            unique.append(record)
    return unique

def gradient_descent(grad_fn, initial_params, learning_rate=0.01, max_iter=1000, tol=1e-6):
    params = list(initial_params)
    for iteration in range(max_iter):
        gradients = grad_fn(params)
        new_params = [p - learning_rate * g for p, g in zip(params, gradients)]
        if max(abs(np - op) for np, op in zip(new_params, params)) < tol:
            return new_params, iteration
        params = new_params
    return params, max_iter
